// Real 16 × 16 encoded images with EXIF GPS/description and XMP metadata.
// JPEG also has a metadata COM segment between progressive scans; PNG has text.
export const sentinel = 'synthetic-glove-request-photo-metadata'

const encodedPhotos = [
  ['image/jpeg', ''],
  ['image/png', ''],
  ['image/webp', ''],
]

export function requestPhotoFixtures() {
  return encodedPhotos.map(([mediaType, base64], index) => ({
    mediaType, base64, caption: `synthetic-glove-request-photo-${index + 1}`,
  }))
}
